window.TRIO_OCASIOES={"casamento":{"meta":{"title":"Espaço para casamento em SP com gastronomia | Grupo TRIO","description":"10 espaços para casamento em São Paulo com cerimônia e festa no mesmo endereço, gastronomia própria e equipe do Grupo TRIO.","url":"https://www.grupotrio.com.br/casamentos/"},"blocks":[{"name":"HERO","paras":["O lugar é parte importante da história que vocês estão começando a escrever. No Grupo TRIO, são 10 espaços para casamento em São Paulo, do jantar para poucos ao coquetel para até 650 convidados, com gastronomia própria e endereços que recebem cerimônia e festa no mesmo local."],"cards":[],"spaces":[],"faqs":[],"numbers":[{"value":"10","label":"ESPAÇOS EM SÃO PAULO"},{"value":"650","label":"CONVIDADOS NO SP HALL"},{"value":"34º","label":"ANDAR NO SKY LOUNGE"}],"eyebrow":"OCASIÃO · CASAMENTOS","title":"Espaços para casamento em São Paulo","cta1":"QUERO PLANEJAR MEU CASAMENTO","cta2":"VER ESPAÇOS","link":"WHATSAPP","key":"hero"},{"name":"SOBRE O TRIO","paras":["O casamento começa muito antes do grande dia. Começa quando vocês escolhem o lugar, provam o primeiro menu, imaginam a cerimônia, escolhem a música e percebem que, aos poucos, tudo começa a tomar forma.","No Grupo TRIO são 10 espaços com possibilidades bem diferentes, do rooftop no 34º andar ao salão cercado de verde. Em alguns endereços, cerimônia e festa acontecem no mesmo lugar, tornando o percurso dos convidados mais simples e deixando o dia ainda mais fluido.","A gastronomia é nossa. A equipe também. Isso significa que vocês têm por perto quem conhece o espaço, entende o menu e acompanha cada etapa até o último brinde.","Há três décadas recebemos casamentos em São Paulo, e a maior parte dos casais que chega até nós vem pela indicação de quem já celebrou aqui."],"cards":[{"num":"01","title":"QUATRO REGIÕES DE SÃO PAULO","desc":"Berrini, Vila Olímpia, Bela Vista e Butantã. Todos os endereços contam com valet, segurança e ar-condicionado."},{"num":"02","title":"GASTRONOMIA PRÓPRIA","desc":"O menu é desenvolvido com o casal e passa por degustação antes da contratação, para que vocês conheçam os sabores que estarão à mesa."},{"num":"03","title":"CERIMÔNIA E FESTA NO MESMO ENDEREÇO","desc":"No Berrini One, TRIO | PÉRGOLA e TRIO | ONE ficam no mesmo andar. No Butantã, TRIO | GARDEN e RIVER ONE estão no mesmo prédio. O TRIO I TRIVENTO possui um foyer para a cerimônia. O TRIO I GARDEN, TRIO I DEZENOVE e TRIO I ONE recebem casamentos intimistas com cerimônia e festa no mesmo local."},{"num":"04","title":"CENÁRIOS QUE FAZEM PARTE DO DIA","desc":"Skyline, heliponto para sessão de fotos, jardim interno, terraço e luz natural. Cada espaço oferece possibilidades diferentes para celebrar e fotografar."}],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"Um casamento pensado para vocês","title":"Um casamento pensado para vocês","cta1":"SOLICITAR ORÇAMENTO","link":"FALAR NO WHATSAPP","key":"sobre"},{"name":"LOCAIS","paras":[],"cards":[],"spaces":[{"name":"TRIO | TRIVENTO","meta":"Bela Vista · 620 m² entre salão, foyer e recepção · Até 600 convidados em coquetel","paras":["O foyer recebe os convidados enquanto o salão permanece fechado, o que permite fazer a cerimônia ali e preservar o efeito da entrada no salão principal."],"feats":["Sala VIP","Valet","Acessibilidade","Ar-condicionado"],"key":"trivento"},{"name":"TRIO | SP HALL","meta":"Vila Olímpia · 840 m² · Até 650 convidados em coquetel e 350 em jantar","paras":["O bosque recebe a cerimônia ao ar livre, e o salão permite diferentes propostas de cenografia, iluminação e ambientação, com liberdade para construir uma celebração com a identidade do casal."],"feats":["Camarim","Salas de apoio","Edifício LEED","Bosque para cerimônia"],"key":"sphall"},{"name":"TRIO | PÉRGOLA","meta":"Berrini · Mais de 800 m² · Até 500 convidados em coquetel e 350 em jantar","paras":["As janelas panorâmicas acompanham a mudança da luz ao longo do dia, e a pérgola cria um espaço a mais para receber, conversar ou respirar entre um momento e outro da festa."],"feats":["Heliponto","Sala VIP","Terraço","Valet","Edifício LEED"],"key":"pergola"},{"name":"TRIO | ONE","meta":"Berrini, 8º andar · 230 m² · Até 200 convidados em coquetel e 120 em jantar","paras":["A iluminação dimerizada acompanha a mudança do dia para a noite, e o salão comporta cerimônia e festa no mesmo ambiente, em celebrações mais intimistas.","No mesmo andar do TRIO | PÉRGOLA, também é possível realizar a cerimônia em um espaço e a recepção no outro, sem que os convidados precisem sair do endereço."],"feats":["Camarim","Heliponto para fotos","Terraço","Valet","Ar-condicionado"],"key":"one"},{"name":"TRIO | SKY LOUNGE","meta":"Berrini, 34º andar · 280 m² · Até 180 convidados em coquetel","paras":["No 34º andar, São Paulo se abre pelas grandes superfícies envidraçadas.","O TRIO | SKY LOUNGE combina com celebrações menores, jantar sentado, um brinde ao pôr do sol e aqueles casamentos em que a vista também faz parte da escolha."],"feats":["Heliponto","Vista panorâmica","Acessibilidade","Edifício LEED"],"key":"skylounge"},{"name":"TRIO | DEZENOVE","meta":"Vila Olímpia, 19º andar · 280 m² · Até 200 convidados em coquetel e 120 em jantar","paras":["No 19º andar do E-Tower, o skyline da Vila Olímpia entra pelas janelas e o jardim interno traz luz natural para o salão.","Um espaço para celebrações mais reservadas, em que a lista é menor e cada convidado tem um lugar importante na história do casal. Cerimônia e festa acontecem no mesmo ambiente."],"feats":["Heliponto","Jardim interno","Camarim","Sala VIP","Gerador"],"key":"dezenove"},{"name":"TRIO | GARDEN","meta":"Butantã · 270 m² · Até 200 convidados em coquetel e 120 em jantar","paras":["A luz natural muda ao longo do dia e cria diferentes possibilidades para a cerimônia, as fotos e a festa, que podem acontecer todas no mesmo lugar.","Para quem quer celebrar cercado de verde, sem abrir mão da cidade."],"feats":["Natureza integrada","Térreo","Acessibilidade","Edifício LEED"],"key":"garden"}],"faqs":[],"numbers":[],"eyebrow":"LOCAIS","title":"Espaços para casamento por região de São Paulo","lead":"Cada espaço, uma maneira de celebrar. A escolha pode começar pelo número de convidados, pelo formato da festa, pela localização ou simplesmente pelo cenário que fez vocês imaginarem o grande dia. Conheça cada espaço e descubra qual combina com a celebração que vocês têm em mente.","key":"locais"},{"name":"SKYLINE","paras":["Há casamentos em que a cidade faz parte da escolha. No momento dos votos, no brinde ao pôr do sol ou naquela foto que vocês vão guardar por muitos anos, São Paulo pode estar ali, do outro lado do vidro.","Do 34º andar, o horizonte se abre. Do 19º, o skyline chega mais perto. No TRIO | PÉRGOLA e no TRIO | ONE, as janelas panorâmicas acompanham a mudança da luz. Cada horário cria uma atmosfera diferente, e nos helipontos o ensaio acontece com a cidade acesa, ao entardecer ou à noite."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"SKYLINE","title":"São Paulo como cenário para o grande dia","cta1":"QUERO ESSE CENÁRIO","link":"VER ESPAÇOS COM VISTA","key":"vista"},{"name":"GASTRONOMIA","paras":["A gastronomia é parte importante de qualquer celebração, e no Grupo TRIO ela começa muito antes do casamento. O menu é desenvolvido com o casal e por quem estará responsável por executá-lo no grande dia.","A inspiração é mediterrânea, com referências que passeiam pelo clássico e pelo contemporâneo. O cardápio se adapta ao formato da festa, ao horário e às características da lista de convidados, com opções veganas, temáticas e linha kosher certificada.","E, antes de decidir, vocês provam. A degustação é o momento de conhecer os sabores, conversar sobre possibilidades e encontrar o menu que tem a ver com vocês."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"GASTRONOMIA","title":"Uma gastronomia feita para o dia de vocês","cta1":"SOLICITAR CARDÁPIO","key":"gastro"},{"name":"PERGUNTAS FREQUENTES","paras":[],"cards":[],"spaces":[],"faqs":[{"q":"Qual é a capacidade para casamentos no Grupo TRIO?","a":[{"li":false,"t":"A capacidade varia de acordo com o formato da celebração. Em um coquetel, os convidados circulam pelo espaço e a capacidade é maior. Em um jantar sentado, é necessário considerar as mesas e o conforto de todos."},{"li":false,"t":"Em coquetel"},{"li":true,"t":"TRIO | SP HALL, até 650 convidados"},{"li":true,"t":"TRIO | TRIVENTO, até 600 convidados"},{"li":true,"t":"TRIO | PÉRGOLA, até 500 convidados"},{"li":true,"t":"TRIO | DEZENOVE, TRIO | ONE e TRIO | GARDEN, até 200 convidados"},{"li":true,"t":"TRIO | SKY LOUNGE, até 180 convidados"},{"li":false,"t":"Em jantar sentado"},{"li":true,"t":"TRIO | TRIVENTO, TRIO | SP HALL e TRIO | PÉRGOLA, até 350 convidados"},{"li":true,"t":"TRIO | DEZENOVE, até 120 convidados"},{"li":true,"t":"TRIO | ONE e TRIO | GARDEN, até 120 convidados"},{"li":false,"t":"A ficha de cada espaço apresenta as capacidades nos dois formatos."}]},{"q":"Em quais bairros de São Paulo estão os espaços para casamento?","a":[{"li":false,"t":"Os espaços sugeridos para casamento estão distribuídos entre quatro regiões de São Paulo:"},{"li":true,"t":"Berrini, TRIO | PÉRGOLA, TRIO | ONE e TRIO | SKY LOUNGE, no Edifício Berrini One"},{"li":true,"t":"Vila Olímpia, TRIO | SP HALL, no São Paulo Corporate Towers"},{"li":true,"t":"Vila Olímpia, TRIO | DEZENOVE, no 19º andar do E-Tower"},{"li":true,"t":"Bela Vista, TRIO | TRIVENTO"},{"li":true,"t":"Butantã, TRIO | GARDEN, no Edifício River One"},{"li":false,"t":"Na Berrini, três espaços ficam no mesmo edifício, o que permite combinar ambientes sem trocar de local."}]},{"q":"A gastronomia está incluída no casamento?","a":[{"li":false,"t":"Sim. A gastronomia é própria do Grupo TRIO e faz parte da proposta desde o início."},{"li":false,"t":"O menu é desenvolvido com o casal e passa por degustação antes da contratação. Trabalhamos com opções veganas, temáticas e linha kosher certificada pela Beit Yaacov, sob supervisão do Rabino Alberto Safra."}]},{"q":"Dá para fazer a cerimônia e a festa no mesmo endereço?","a":[{"li":false,"t":"Sim, e de três maneiras diferentes."},{"li":false,"t":"Em salões vizinhos: no Berrini One, o TRIO | ONE e o TRIO | PÉRGOLA ficam no mesmo andar. A cerimônia acontece em um e a recepção no outro, com os convidados apenas atravessando o hall."},{"li":false,"t":"Em áreas do próprio espaço: o TRIO | TRIVENTO tem foyer para a cerimônia, com o salão principal abrindo em seguida. O TRIO | SP HALL tem um bosque para cerimônia ao ar livre."},{"li":false,"t":"No mesmo ambiente: em celebrações intimistas, o TRIO | GARDEN, o TRIO | DEZENOVE e o TRIO | ONE recebem cerimônia e festa no mesmo salão."}]},{"q":"É possível realizar um mini wedding no Grupo TRIO?","a":[{"li":false,"t":"Sim. O TRIO | SKY LOUNGE, o TRIO | ONE, o TRIO | DEZENOVE e o TRIO | GARDEN funcionam bem para celebrações entre 80 e 150 convidados, em jantar sentado ou coquetel reduzido."},{"li":false,"t":"É uma escolha para casais que preferem uma celebração mais próxima, concentrando a atenção na gastronomia, na produção e nas pessoas que estarão à mesa."}]},{"q":"Quais espaços têm vista para o skyline de São Paulo?","a":[{"li":false,"t":"Quatro espaços oferecem diferentes perspectivas da cidade."},{"li":false,"t":"O TRIO | SKY LOUNGE ocupa o 34º andar do Berrini One e é o ponto mais alto do Grupo TRIO. O TRIO | DEZENOVE fica no 19º andar do E-Tower, com vista para o skyline da Vila Olímpia. O TRIO | PÉRGOLA combina janelas panorâmicas com 200 m² de pérgola voltados para a cidade. E o TRIO | ONE tem uma lateral inteira envidraçada, no mesmo edifício do PÉRGOLA."}]},{"q":"O que já está incluído na estrutura do espaço?","a":[{"li":false,"t":"Mobiliário próprio, ar-condicionado, segurança e valet estão em todos os endereços. Os demais recursos variam:"},{"li":true,"t":"Sala VIP, TRIO | TRIVENTO, TRIO | PÉRGOLA e TRIO | DEZENOVE"},{"li":true,"t":"Camarim, TRIO | SP HALL, TRIO | ONE e TRIO | DEZENOVE"},{"li":true,"t":"Heliponto, TRIO | PÉRGOLA, TRIO | ONE, TRIO | SKY LOUNGE e TRIO | DEZENOVE"},{"li":true,"t":"Terraço para fumantes, TRIO | PÉRGOLA e TRIO | ONE"},{"li":true,"t":"Gerador em stand by, TRIO | DEZENOVE e TRIO | GARDEN"},{"li":true,"t":"Acessibilidade, TRIO | TRIVENTO, TRIO | SP HALL, TRIO | SKY LOUNGE e TRIO | GARDEN"},{"li":true,"t":"Certificação LEED, TRIO | PÉRGOLA, TRIO | SP HALL, TRIO | SKY LOUNGE e TRIO | GARDEN"},{"li":false,"t":"Na ficha de cada espaço, a lista completa."}]},{"q":"Como solicitar um orçamento para casamento no Grupo TRIO?","a":[{"li":false,"t":"Preencha o formulário desta página ou fale diretamente com a nossa equipe pelo WhatsApp."},{"li":false,"t":"Se já tiver essas informações, envie a data prevista, o número aproximado de convidados e o formato desejado. A partir disso, conseguimos entender melhor o que vocês estão planejando e indicar os espaços mais adequados."},{"li":false,"t":"Nossa equipe retorna em até 24 horas úteis com uma proposta personalizada."},{"li":false,"t":"O mesmo canal também pode ser utilizado para solicitar informações sobre mini wedding, festa de 15 anos, aniversário e Bar e Bat Mitzvah."}]}],"numbers":[],"eyebrow":"PERGUNTAS FREQUENTES","title":"Tudo sobre casamentos no Grupo TRIO","link":"FALAR COM A EQUIPE","key":"faq"},{"name":"CONTATO","paras":["O primeiro passo pode ser uma conversa. Contem para a nossa equipe o que vocês imaginam para esse dia: a data, o número de convidados, o formato da celebração e o que é importante para vocês.","A partir daí, apresentamos os espaços, a gastronomia e as possibilidades que fazem sentido para o casamento de vocês. O retorno vem em até 24 horas úteis com uma proposta personalizada, e a visita pode ser agendada na mesma conversa, com quem vai acompanhar vocês ao longo do planejamento."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"CONTATO","title":"Vamos planejar seu casamento?","formFields":["nome completo","e-mail","telefone","tipo de casamento","data prevista","nº de convidados","mensagem"],"cta1":"ENVIAR SOLICITAÇÃO","key":"contato"}]},"15anos":{"meta":{"title":"Festa de 15 anos em SP: espaços e gastronomia | Grupo TRIO","description":"10 espaços para festa de 15 anos em São Paulo. Conheça os espaços do Grupo TRIO, com gastronomia própria, estrutura completa e atendimento de alto padrão.","url":"https://www.grupotrio.com.br/festa-de-15-anos/"},"blocks":[{"name":"HERO","paras":["Os 15 anos acontecem uma vez. O espaço certo ajuda a transformar essa celebração em uma noite que traduza este momento.","O Grupo TRIO reúne espaços para festa de 15 anos em São Paulo, com diferentes estilos, capacidades e possibilidades de produção. Em todos eles, gastronomia própria e uma equipe que acompanha a família do planejamento ao último brinde."],"cards":[],"spaces":[],"faqs":[],"numbers":[{"value":"10","label":"ESPAÇOS EM SÃO PAULO"},{"value":"650","label":"CONVIDADOS NO SP HALL"},{"value":"19º","label":"ANDAR NO DEZENOVE"}],"eyebrow":"OCASIÃO · FESTA DE 15 ANOS","title":"Espaços para festa de 15 anos em São Paulo","cta1":"QUERO FAZER A FESTA DELA","cta2":"VER ESPAÇOS","link":"FALAR NO WHATSAPP","key":"hero"},{"name":"SOBRE A EXPERIÊNCIA","paras":["A debutante costuma chegar com muitas ideias: a música da entrada, a decoração, a pista, as cores e todos os detalhes que fazem a festa ser dela.","A família chega com outras perguntas: quantas pessoas cabem, como funciona a gastronomia, onde os convidados serão recebidos e quem vai cuidar de tudo no dia.","No TRIO, os dois lados fazem parte do planejamento.","São 10 espaços para festa de 15 anos em São Paulo, com tamanhos e propostas diferentes. A gastronomia é nossa, a equipe acompanha o evento de ponta a ponta e o planejamento é construído junto com vocês.","São três décadas realizando celebrações em São Paulo, e a maior parte das famílias chega pela indicação de quem já festejou aqui."],"cards":[{"num":"01","title":"QUATRO REGIÕES DE SÃO PAULO","desc":"Berrini, Vila Olímpia, Bela Vista e Butantã. Diferentes endereços para escolher o cenário que combina com a festa."},{"num":"02","title":"GASTRONOMIA DA CASA","desc":"A gastronomia é nossa e o menu é desenvolvido junto com vocês. Antes da decisão final, vocês conhecem e degustam a proposta."},{"num":"03","title":"DE 30 A 650 CONVIDADOS","desc":"Do formato mais intimista às grandes celebrações, os espaços recebem diferentes tamanhos de lista e configurações de evento."},{"num":"04","title":"A ENTRADA, A VALSA E A PISTA","desc":"A festa acontece como uma sequência. Recepção, entrada da debutante, jantar, valsa e pista são planejados para que cada momento aconteça no seu tempo, sem perder o ritmo da noite."}],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"SOBRE A EXPERIÊNCIA","title":"Uma festa com a cara dela e tranquilidade para a família","cta1":"RECEBER UMA PROPOSTA","link":"FALAR NO WHATSAPP","key":"sobre"},{"name":"LOCAIS","paras":[],"cards":[],"spaces":[{"name":"TRIO | TRIVENTO","meta":"Bela Vista · 620 m² · até 600 convidados em coquetel.","paras":["Isso permite guardar um dos momentos mais esperados da noite para a hora certa: quando as portas se abrem e a debutante entra.","Com espaço para grandes celebrações, o TRIVENTO é uma opção para listas que passam de 200 convidados e para festas que pedem diferentes momentos ao longo da noite."],"feats":["Sala VIP","Valet","Acessibilidade","Ar-condicionado","Pé-direito alto"],"key":"trivento"},{"name":"TRIO | SP HALL","meta":"Vila Olímpia · 840 m² · até 650 convidados em coquetel e 350 no jantar.","paras":["Dentro do São Paulo Corporate Towers, o SP HALL combina amplitude, áreas verdes e pé-direito alto.","O espaço permite trabalhar cenografia suspensa, projeção, iluminação e diferentes configurações para a festa.","É um dos maiores salões do TRIO e uma escolha para quem quer espaço para criar uma celebração de grande porte."],"feats":["Camarim","Salas de apoio","Heliponto","Edifício LEED","Acessibilidade"],"key":"sphall"},{"name":"TRIO | PÉRGOLA","meta":"Berrini · mais de 800 m² · até 500 convidados em coquetel e 350 no jantar","paras":["No Berrini One, o PÉRGOLA reúne salão, pérgola, terraço e vista para a cidade.","A pérgola cria um espaço de transição entre o coquetel e a pista, permitindo que a festa mude de ritmo naturalmente.","No heliponto do edifício, a sessão de fotos acontece com a cidade inteira ao fundo."],"feats":["Heliponto","Sala VIP","Terraço","Valet","Edifício LEED"],"key":"pergola"},{"name":"TRIO | DEZENOVE","meta":"Vila Olímpia, 19º andar · 280 m² · até 200 convidados em coquetel e 120 no jantar","paras":["No 19º andar do E-Tower, o DEZENOVE traz o skyline da Vila Olímpia para dentro da festa.","O jardim interno adiciona luz natural ao ambiente e cria uma atmosfera diferente ao longo do dia.","É uma opção para festas com listas menores, que querem um espaço marcante sem abrir mão de uma atmosfera especial. No heliponto, a sessão de fotos tem a cidade como fundo."],"feats":["Heliponto","Jardim interno","Camarim","Sala VIP","Gerador"],"key":"dezenove"},{"name":"TRIO | GARDEN","meta":"Butantã · 270 m² · até 200 convidados em coquetel e 120 no jantar","paras":["Mais de 25 espécies de plantas cercam o salão do GARDEN e trazem a natureza para dentro da celebração.","A luz natural muda completamente o ambiente e cria diferentes possibilidades para fotos e ambientação.","Uma escolha para quem quer uma festa de 15 anos mais próxima da natureza, sem sair de São Paulo."],"feats":["Natureza integrada","Térreo","Gerador","Acessibilidade"],"key":"garden"},{"name":"TRIO | ONE","meta":"Berrini, 8º andar · 230 m² · até 200 convidados em coquetel e 120 no jantar","paras":["A lateral envidraçada do ONE transforma a cidade em parte da decoração.","A iluminação dimerizada acompanha a passagem do dia para a noite, e o salão comporta a festa inteira em um só ambiente."],"feats":["Camarim","Sala VIP","Heliponto","Terraço","Edifício LEED"],"key":"one"},{"name":"TRIO | SKY LOUNGE","meta":"Berrini, 34º andar · 280 m² · até 180 convidados em coquetel","paras":["No ponto mais alto do grupo, São Paulo se abre pelas grandes superfícies envidraçadas.","O teto em balanço amplia a sensação de espaço, e a vista acompanha a festa do fim da tarde à noite.","É a escolha para listas curtas, em jantar sentado ou coquetel reduzido, com brinde ao pôr do sol."],"feats":["Heliponto","Vista panorâmica","Acessibilidade","Edifício LEED"],"key":"skylounge"},{"name":"TRIO | RIVER ONE","meta":"Butantã · 370 m² · até 200 convidados em coquetel e 100 no jantar","paras":["No mesmo endereço do GARDEN, auditório e foyer se integram em um só percurso.","A projeção mapeada em 360º transforma as paredes em parte da decoração, o que abre espaço para homenagens em vídeo e cenografia autoral.","É a escolha para festas que querem produção audiovisual como parte da noite."],"feats":["Projeção mapeada 360º","Estrutura audiovisual","Amplo foyer","Camarim","Gerador"],"key":"riverone"}],"faqs":[],"numbers":[],"eyebrow":"LOCAIS","title":"Espaços para festa de 15 anos por região de São Paulo","lead":"A escolha começa pela lista de convidados e pelo formato da festa. Depois vem o cenário, a dinâmica da noite e tudo o que a debutante imagina para a celebração. Conheça os espaços do TRIO e encontre aquele que combina com o tamanho e o estilo da festa.","key":"locais"},{"name":"SKYLINE","paras":["As portas se abrem, a debutante aparece e, atrás dela, São Paulo inteira acesa.","É a vista que as fotos vão guardar: ela em primeiro plano, a cidade lá embaixo e nenhuma parede atrás. No TRIO | SKY LOUNGE, do 34º andar, o horizonte se abre por completo. No TRIO | DEZENOVE, o skyline da Vila Olímpia entra pelas janelas do 19º. E no TRIO | PÉRGOLA e no TRIO | ONE, as janelas panorâmicas acompanham a mudança da luz até o fim da noite."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"SKYLINE","title":"A cidade como cenário para a entrada","cta1":"CONHECER OS ESPAÇOS COM VISTA","link":"VER ESPAÇOS COM VISTA","key":"vista"},{"name":"GASTRONOMIA","paras":["Em uma festa de 15 anos, existem dois ritmos acontecendo ao mesmo tempo. Os adolescentes circulam, dançam e querem opções práticas para acompanhar a noite. Os adultos aproveitam a mesa e a conversa.","Por isso o menu é construído com vocês, considerando os diferentes momentos da festa e os convidados.","A cozinha é própria, e a mesma brigada que assina os nossos restaurantes participa da criação dos menus, com inspiração mediterrânea e opções que transitam entre o clássico e o contemporâneo. Há também opções veganas, menus temáticos e linha kosher certificada.","Antes de decidir, vocês degustam o menu. E, se quiserem conhecer a cozinha de perto, podem almoçar no Restaurante TRIO | DEZENOVE ou no Restaurante TRIO | GARDEN."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"GASTRONOMIA","title":"Um menu pensado para a festa e para todos que estão nela","cta1":"CONHECER AS OPÇÕES DE MENU","key":"gastro"},{"name":"PERGUNTAS FREQUENTES","paras":[],"cards":[],"spaces":[],"faqs":[{"q":"Qual é a capacidade dos espaços para festa de 15 anos?","a":[{"li":false,"t":"A capacidade depende do formato escolhido. Em um coquetel, os convidados circulam e o espaço comporta mais pessoas. Em um jantar sentado, é preciso considerar o espaço ocupado pelas mesas."},{"li":false,"t":"Em coquetel"},{"li":true,"t":"TRIO | SP HALL, até 650 convidados"},{"li":true,"t":"TRIO | TRIVENTO, até 600"},{"li":true,"t":"TRIO | PÉRGOLA, até 500"},{"li":true,"t":"TRIO | DEZENOVE, até 200"},{"li":true,"t":"TRIO | GARDEN, até 200"},{"li":true,"t":"TRIO | ONE, até 200"},{"li":true,"t":"TRIO | RIVER ONE, até 200"},{"li":true,"t":"TRIO | SKY LOUNGE, até 180"},{"li":false,"t":"Em jantar sentado"},{"li":true,"t":"TRIO | TRIVENTO, até 350"},{"li":true,"t":"TRIO | SP HALL, até 350"},{"li":true,"t":"TRIO | PÉRGOLA, até 350"},{"li":true,"t":"TRIO | DEZENOVE, até 120"},{"li":true,"t":"TRIO | GARDEN, até 120"},{"li":true,"t":"TRIO | RIVER ONE, até 100"},{"li":true,"t":"TRIO | ONE, até 120"},{"li":false,"t":"A ficha de cada espaço apresenta as capacidades de acordo com o formato."}]},{"q":"Em quais bairros de São Paulo ficam os espaços para festa de 15 anos?","a":[{"li":false,"t":"Os espaços sugeridos para festa de 15 anos estão distribuídos pela Zona Sul e por importantes eixos da cidade."},{"li":true,"t":"Berrini, TRIO | PÉRGOLA, TRIO | ONE e TRIO | SKY LOUNGE, no Edifício Berrini One"},{"li":true,"t":"Vila Olímpia, TRIO | SP HALL, no São Paulo Corporate Towers"},{"li":true,"t":"Vila Olímpia, TRIO | DEZENOVE, no 19º andar do E-Tower"},{"li":true,"t":"Bela Vista, TRIO | TRIVENTO"},{"li":true,"t":"Butantã, TRIO | GARDEN e TRIO | RIVER ONE, no Edifício River One"},{"li":false,"t":"O acesso ao Butantã é facilitado pela Marginal Pinheiros e pelas avenidas Faria Lima e Rebouças."}]},{"q":"Dá para fazer a valsa e a entrada da debutante no mesmo salão?","a":[{"li":false,"t":"Sim. A entrada e a valsa são planejadas de acordo com o espaço e o formato da festa."},{"li":false,"t":"Nos espaços com foyer independente, como o TRIO | TRIVENTO e o TRIO | PÉRGOLA, os convidados são recebidos fora do salão principal, que permanece fechado até a hora da entrada. Assim, a chegada da debutante ganha o seu próprio momento, e a festa segue naturalmente depois."}]},{"q":"A gastronomia está incluída na festa de 15 anos?","a":[{"li":false,"t":"Sim. A gastronomia é própria do Grupo TRIO e faz parte da proposta desde o início."},{"li":false,"t":"O menu é desenvolvido junto com vocês, considerando o perfil da festa e os convidados, e passa por degustação antes da assinatura. Contempla opções veganas, menus temáticos e linha kosher certificada pela Beit Yaacov, sob supervisão do Rabino Alberto Safra."}]},{"q":"Quais espaços têm vista para o skyline de São Paulo?","a":[{"li":false,"t":"Quatro espaços têm vista aberta para a cidade."},{"li":false,"t":"O TRIO | SKY LOUNGE ocupa o 34º andar do Berrini One e é o ponto mais alto do grupo. O TRIO | DEZENOVE fica no 19º andar do E-Tower e traz o skyline da Vila Olímpia para a festa. O TRIO | PÉRGOLA tem janelas panorâmicas e 200 m² de pérgola voltados para a cidade. E o TRIO | ONE tem uma lateral inteira envidraçada, no mesmo edifício do PÉRGOLA."}]},{"q":"É possível fazer uma festa de 15 anos mais intimista?","a":[{"li":false,"t":"Sim. O TRIO | SKY LOUNGE, o TRIO | ONE, o TRIO | DEZENOVE e o TRIO | GARDEN funcionam bem para listas menores, em jantar sentado ou coquetel reduzido."},{"li":false,"t":"São espaços que permitem concentrar a experiência na gastronomia, na produção e nos detalhes da celebração, sem a necessidade de um salão de grande porte."}]},{"q":"O que já está incluído na estrutura do espaço?","a":[{"li":false,"t":"Todos os endereços contam com mobiliário próprio, ar-condicionado, segurança, valet e acessibilidade. Os demais recursos variam:"},{"li":true,"t":"Camarim, TRIO | SP HALL, TRIO | ONE, TRIO | PÉRGOLA, TRIO | DEZENOVE, TRIO | TRIVENTO, TRIO | RIVER ONE, TRIO | GARDEN, TRIO | METROPOLITAN."},{"li":true,"t":"Sala VIP, TRIO | SP HALL, TRIO | ONE, TRIO | PÉRGOLA, TRIO | DEZENOVE, TRIO | TRIVENTO, TRIO | RIVER ONE, TRIO | GARDEN, TRIO | METROPOLITAN."},{"li":true,"t":"Heliponto, TRIO | PÉRGOLA, TRIO | ONE, TRIO | SKY LOUNGE, TRIO | DEZENOVE e TRIO | SP HALL, TRIO | METROPOLITAN."},{"li":true,"t":"Gerador em stand-by, TRIO | DEZENOVE, TRIO | GARDEN, TRIO | METROPOLITAN e TRIO | RIVER ONE."},{"li":true,"t":"Terraço para fumantes, TRIO | PÉRGOLA e TRIO | ONE."},{"li":true,"t":"Acessibilidade, TRIO | SP HALL, TRIO | ONE, TRIO | PÉRGOLA, TRIO | DEZENOVE, TRIO | TRIVENTO, TRIO | RIVER ONE, TRIO | GARDEN, TRIO | METROPOLITAN, TRIO | SKY LOUNGE."},{"li":true,"t":"Certificação LEED, TRIO | SP HALL, TRIO | ONE, TRIO | PÉRGOLA, TRIO | DEZENOVE, TRIO | SKY LOUNGE"},{"li":false,"t":"Na página de cada espaço, você encontra a estrutura completa."}]},{"q":"Como solicitar um orçamento para a festa de 15 anos?","a":[{"li":false,"t":"O primeiro passo é conversar com a nossa equipe. Você pode preencher o formulário desta página ou falar diretamente pelo WhatsApp."},{"li":false,"t":"Ajuda ter em mãos a data prevista, o número aproximado de convidados e o formato que vocês imaginam para a festa. A equipe do TRIO retorna em até 24 horas úteis com uma proposta personalizada."},{"li":false,"t":"O mesmo atendimento está disponível para casamento, aniversário, mini wedding, Bar e Bat Mitzvah e eventos corporativos."}]}],"numbers":[],"eyebrow":"PERGUNTAS FREQUENTES","title":"Tudo sobre festa de 15 anos no Grupo TRIO","lead":"Reunimos algumas das principais dúvidas das famílias na hora de escolher o espaço, pensar a entrada da debutante, definir a gastronomia e começar o planejamento. Se a sua dúvida não estiver aqui, nossa equipe está à disposição para conversar.","link":"FALAR COM A EQUIPE","key":"faq"},{"name":"CONTATO","paras":["A festa é dela. O planejamento pode ser de vocês.","Conte para a nossa equipe como estão imaginando essa celebração. A partir da data, do número de convidados e do estilo da festa, ajudamos vocês a encontrar o espaço e a proposta que fazem sentido para esse momento.","Retornamos em até 24 horas úteis com uma proposta personalizada, e a visita pode ser agendada na mesma conversa, com a debutante junto, claro."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"CONTATO","title":"Vamos planejar a festa de 15 anos?","formFields":["nome completo","e-mail","telefone","tipo de evento","data prevista","nº de convidados","mensagem"],"cta1":"ENVIAR SOLICITAÇÃO","key":"contato"}]},"aniversario":{"meta":{"title":"Espaço para aniversário em SP com gastronomia | Grupo TRIO","description":"10 espaços para aniversário em São Paulo, da Berrini à Bela Vista, com gastronomia própria, capacidade de 30 a 650 convidados e equipe do Grupo TRIO.","url":"https://www.grupotrio.com.br/aniversario/"},"blocks":[{"name":"HERO","paras":["Seu aniversário começa pelo espaço certo. Em São Paulo, o Grupo TRIO reúne espaços para diferentes estilos de celebração, de um jantar mais intimista a uma grande festa. Cada endereço tem uma personalidade própria, com gastronomia da casa, estrutura completa e uma equipe que acompanha você do planejamento ao último convidado."],"cards":[],"spaces":[],"faqs":[],"numbers":[{"value":"10","label":"ESPAÇOS EM SÃO PAULO"},{"value":"650","label":"CONVIDADOS NO SP HALL"},{"value":"34º","label":"ANDAR NO SKY LOUNGE"}],"eyebrow":"OCASIÃO · ANIVERSÁRIOS","title":"Espaços para aniversário em São Paulo","cta1":"QUERO FAZER MEU ANIVERSÁRIO","cta2":"VER ESPAÇOS","link":"WHATSAPP","key":"hero"},{"name":"SOBRE A EXPERIÊNCIA","paras":["Cada celebração tem um jeito de acontecer. Pode ser um jantar para poucos, um almoço entre amigos, um coquetel ao pôr do sol ou uma festa que reúne centenas de convidados.","Por isso temos espaços diferentes, com propostas, capacidades e cenários que acompanham cada tipo de comemoração. No TRIO, a gastronomia é da casa, a equipe é nossa e a estrutura também, então você fala com um único time, do primeiro contato ao pós-evento.","São três décadas realizando celebrações em São Paulo, e a maior parte dos nossos clientes chega pela indicação de quem já festejou aqui."],"cards":[{"num":"01","title":"CINCO REGIÕES DE SÃO PAULO","desc":"Berrini, Vila Olímpia, Jardim Europa, Butantã e Bela Vista. Os espaços contam com estrutura para receber diferentes formatos de celebração."},{"num":"02","title":"GASTRONOMIA DA CASA","desc":"Nossa gastronomia faz parte da experiência. O menu é construído de acordo com o perfil da celebração e degustado antes da assinatura."},{"num":"03","title":"DE 30 A 650 CONVIDADOS","desc":"Do aniversário mais intimista às grandes festas, os espaços recebem diferentes tamanhos de lista e formatos de evento."},{"num":"04","title":"CENÁRIOS QUE FAZEM PARTE DA FESTA","desc":"Vista para São Paulo, heliponto, jardim interno e terraços. Cada endereço cria um cenário próprio para celebrar."}],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"SOBRE A EXPERIÊNCIA","title":"Um aniversário do seu jeito, do começo ao fim","cta1":"RECEBER UMA PROPOSTA","link":"FALAR NO WHATSAPP","key":"sobre"},{"name":"LOCAIS","paras":[],"cards":[],"spaces":[{"name":"TRIO | TRIVENTO","meta":"Bela Vista · 620 m² · até 600 convidados","paras":["Um dos maiores espaços do TRIO, o TRIVENTO fica na Bela Vista e foi pensado para grandes celebrações.","O salão se conecta ao foyer e à recepção, criando diferentes possibilidades para a chegada dos convidados, a festa e a circulação ao longo do evento.","É uma escolha para quem tem uma lista grande e quer espaço para criar diferentes momentos durante a celebração."],"feats":["Sala VIP","Valet","Acessibilidade","Ar-condicionado","Pé-direito alto"],"key":"trivento"},{"name":"TRIO | SP HALL","meta":"Vila Olímpia · 840 m² · até 650 convidados","paras":["Dentro do São Paulo Corporate Towers, na Juscelino Kubitschek, o SP HALL combina amplitude, áreas verdes e liberdade para criar diferentes configurações de evento.","O pé-direito alto e a área do salão permitem trabalhar diferentes propostas de cenografia, do jantar à pista de dança."],"feats":["Camarim","Salas de apoio","Heliponto","Edifício LEED","Acessibilidade"],"key":"sphall"},{"name":"TRIO | PÉRGOLA","meta":"Berrini · 800 m² · até 500 convidados","paras":["No Berrini One, o PÉRGOLA combina grandes janelas, vista para a cidade, pérgola e terraço.","O espaço permite organizar diferentes momentos da festa no mesmo endereço, da recepção ao jantar e, depois, à pista."],"feats":["Heliponto","Sala VIP","Terraço","Valet","Edifício LEED"],"key":"pergola"},{"name":"TRIO | SKY LOUNGE","meta":"Berrini, 34º andar · 280 m² · até 180 convidados","paras":["No 34º andar do Berrini One, o SKY LOUNGE coloca São Paulo como parte do cenário.","A vista panorâmica combina com diferentes momentos: um jantar, um brinde ao pôr do sol ou uma celebração para uma lista mais enxuta."],"feats":["Heliponto","Vista panorâmica","Acessibilidade","Edifício LEED"],"key":"skylounge"},{"name":"TRIO | DEZENOVE","meta":"Vila Olímpia, 19º andar · 280 m² · até 200 convidados","paras":["No E-Tower, na Rua Funchal, o DEZENOVE reúne vista para o skyline e um jardim interno que traz luz natural para o salão.","É uma opção para quem quer a cidade como cenário, mas também valoriza um ambiente mais reservado para celebrar."],"feats":["Heliponto","Jardim interno","Camarim","Sala VIP","Gerador"],"key":"dezenove"},{"name":"TRIO | ONE","meta":"Berrini, 8º andar · 230 m² · até 200 convidados","paras":["A lateral envidraçada do ONE traz a cidade para dentro da celebração, enquanto a iluminação dimerizada acompanha as diferentes etapas da noite.","No mesmo andar do PÉRGOLA, o espaço também permite criar uma dinâmica integrada entre recepção e festa."],"feats":["Camarim","Sala VIP","Heliponto para fotos","Terraço","Edifício LEED"],"key":"one"},{"name":"TRIO | GARDEN","meta":"Butantã · 270 m² · até 120 convidados","paras":["No térreo do Edifício River One, o GARDEN tem a natureza como parte do ambiente.","Mais de 25 espécies de plantas cercam o salão e a luz natural acompanha o espaço durante o dia. Uma escolha para aniversários diurnos ou noturnos, almoços mais longos ou celebrações que querem trazer um pouco de verde para dentro da cidade."],"feats":["Natureza integrada","Térreo","Acessibilidade","Gerador"],"key":"garden"},{"name":"TRIO | RIVER ONE","meta":"Butantã · auditório de 170 m² + foyer de 200 m² · até 200 convidados","paras":["No mesmo endereço do GARDEN, o RIVER ONE combina foyer e um espaço imersivo com estrutura audiovisual.","A projeção transforma as paredes em parte da experiência e abre possibilidades para homenagens em vídeo, apresentações, shows e cenografias personalizadas.","O acesso é facilitado pela Marginal Pinheiros e pelas avenidas Faria Lima e Rebouças."],"feats":["Projeção mapeada 360º","Estrutura audiovisual","Amplo foyer","Camarim","Gerador"],"key":"riverone"}],"faqs":[],"numbers":[],"eyebrow":"LOCAIS","title":"Espaços para aniversário por região de São Paulo","lead":"Cada espaço do TRIO tem uma proposta própria. Para escolher, vale começar por dois pontos: quantos convidados você pretende receber e como imagina a celebração. A partir daí, nossa equipe ajuda você a encontrar o espaço que melhor combina com o seu aniversário.","key":"locais"},{"name":"SKYLINE","paras":["Alguns aniversários pedem uma vista que faça parte da celebração.","No TRIO, você pode escolher entre diferentes espaços com skyline de São Paulo. No 34º andar, o SKY LOUNGE coloca a cidade inteira diante dos convidados. No 19º, o DEZENOVE traz o skyline da Vila Olímpia para perto.","São duas perspectivas diferentes da mesma cidade, e diferentes possibilidades para criar a noite que você imaginou."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"SKYLINE","title":"A cidade lá embaixo, a festa aqui em cima","cta1":"QUERO ESSE CENÁRIO","link":"VER ESPAÇOS COM VISTA","key":"vista"},{"name":"GASTRONOMIA","paras":["No TRIO, gastronomia e evento são pensados juntos.","Nossos menus são construídos de acordo com o perfil da celebração, o horário, o formato do evento e os convidados.","A inspiração passa pelo Mediterrâneo, pelos clássicos e pela cozinha contemporânea, sempre buscando equilíbrio entre sabor, apresentação e personalidade.","Também contamos com opções veganas, menus temáticos e linha kosher certificada.","E, antes de escolher, você prova. Além da degustação, dá para conhecer a cozinha em um almoço no Restaurante TRIO | GARDEN ou no Restaurante TRIO | DEZENOVE."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"GASTRONOMIA","title":"Sabores que se tornam memórias","cta1":"CONHECER AS OPÇÕES DE MENU","key":"gastro"},{"name":"PERGUNTAS FREQUENTES","paras":[],"cards":[],"spaces":[],"faqs":[{"q":"Qual é a capacidade dos espaços para aniversário do Grupo TRIO?","a":[{"li":false,"t":"A capacidade depende do formato da celebração. Em um coquetel, os convidados circulam e o espaço comporta uma quantidade maior de pessoas. Já em um jantar sentado, é preciso considerar o espaço ocupado pelas mesas."},{"li":false,"t":"Em coquetel"},{"li":true,"t":"TRIO | SP HALL, até 650 convidados"},{"li":true,"t":"TRIO | TRIVENTO, até 600 convidados"},{"li":true,"t":"TRIO | PÉRGOLA, até 500"},{"li":true,"t":"TRIO | DEZENOVE, TRIO | ONE e TRIO | RIVER ONE, até 200"},{"li":true,"t":"TRIO | SKY LOUNGE, até 180"},{"li":true,"t":"TRIO | METROPOLITAN, até 150"},{"li":false,"t":"Em jantar sentado"},{"li":true,"t":"TRIO | SP HALL, TRIO | PÉRGOLA e TRIO | TRIVENTO, até 350"},{"li":true,"t":"TRIO | METROPOLITAN, até 150"},{"li":true,"t":"TRIO | DEZENOVE, TRIO | ONE e TRIO | GARDEN, até 120"},{"li":true,"t":"TRIO | RIVER ONE, até 100"},{"li":false,"t":"A ficha de cada espaço apresenta as capacidades por formato."}]},{"q":"Em quais bairros de São Paulo ficam os espaços para aniversário?","a":[{"li":false,"t":"Os espaços do TRIO estão distribuídos por diferentes regiões de São Paulo, principalmente nos eixos corporativos da cidade."},{"li":true,"t":"Berrini, TRIO | PÉRGOLA, TRIO | ONE e TRIO | SKY LOUNGE, no Edifício Berrini One"},{"li":true,"t":"Vila Olímpia, TRIO | DEZENOVE, no 19º andar do E-Tower"},{"li":true,"t":"Vila Olímpia, TRIO | SP HALL, no São Paulo Corporate Towers"},{"li":true,"t":"Butantã, TRIO | GARDEN e TRIO | RIVER ONE, no Edifício River One"},{"li":true,"t":"Bela Vista, TRIO | TRIVENTO"},{"li":true,"t":"Jardim Europa, TRIO | METROPOLITAN, de perfil executivo"},{"li":false,"t":"O acesso ao Butantã é facilitado pela Marginal Pinheiros e pelas avenidas Faria Lima e Rebouças."}]},{"q":"A gastronomia está incluída no aniversário?","a":[{"li":false,"t":"Sim. A gastronomia é própria do Grupo TRIO e faz parte da proposta desde o início."},{"li":false,"t":"O menu é desenvolvido de acordo com o perfil do evento e passa por degustação antes da assinatura. Contempla opções veganas, menus temáticos e linha kosher certificada pela Beit Yaacov, sob supervisão do Rabino Alberto Safra."}]},{"q":"Quais espaços têm vista para o skyline de São Paulo?","a":[{"li":false,"t":"Três espaços têm a cidade como parte do cenário."},{"li":false,"t":"O TRIO | SKY LOUNGE fica no 34º andar do Berrini One e é o ponto mais alto do grupo. O TRIO | DEZENOVE fica no 19º andar do E-Tower e traz o skyline da Vila Olímpia para dentro da celebração. Já o TRIO | PÉRGOLA combina janelas panorâmicas com 200 m² de pérgola voltados para a cidade."}]},{"q":"É possível fazer um aniversário intimista?","a":[{"li":false,"t":"Sim, e é um pedido comum entre os aniversários de adulto."},{"li":false,"t":"Para celebrações menores, o TRIO | SKY LOUNGE, o TRIO | ONE e o TRIO | GARDEN funcionam bem em jantar sentado ou coquetel reduzido. Se a celebração for durante o dia, o GARDEN traz luz natural e um ambiente cercado por plantas."},{"li":false,"t":"Vale ler também as ideias para festa de aniversário adulto que reunimos no blog."}]},{"q":"O que já está incluído na estrutura do espaço?","a":[{"li":false,"t":"Mobiliário próprio, ar-condicionado, segurança, valet e acessibilidade estão em todos os endereços. Os demais recursos variam:"},{"li":true,"t":"Camarim, TRIO | SP HALL, TRIO | ONE, TRIO | PÉRGOLA, TRIO | DEZENOVE, TRIO | TRIVENTO, TRIO | RIVER ONE, TRIO | GARDEN, TRIO | METROPOLITAN."},{"li":true,"t":"Sala VIP, TRIO | SP HALL, TRIO | ONE, TRIO | PÉRGOLA, TRIO | DEZENOVE, TRIO | TRIVENTO, TRIO | RIVER ONE, TRIO | GARDEN, TRIO | METROPOLITAN."},{"li":true,"t":"Heliponto, TRIO | PÉRGOLA, TRIO | ONE, TRIO | SKY LOUNGE, TRIO | DEZENOVE e TRIO | SP HALL, TRIO | METROPOLITAN."},{"li":true,"t":"Gerador em stand-by, TRIO | DEZENOVE, TRIO | GARDEN, TRIO | METROPOLITAN e TRIO | RIVER ONE."},{"li":true,"t":"Terraço para fumantes, TRIO | PÉRGOLA e TRIO | ONE."},{"li":true,"t":"Acessibilidade, TRIO | SP HALL, TRIO | ONE, TRIO | PÉRGOLA, TRIO | DEZENOVE, TRIO | TRIVENTO, TRIO | RIVER ONE, TRIO | GARDEN, TRIO | METROPOLITAN, TRIO | SKY LOUNGE."},{"li":true,"t":"Certificação LEED, TRIO | SP HALL, TRIO | ONE, TRIO | PÉRGOLA, TRIO | DEZENOVE, TRIO | SKY LOUNGE."},{"li":false,"t":"Na página de cada espaço, você encontra a estrutura completa."}]},{"q":"Como funcionam a visita e a degustação?","a":[{"li":false,"t":"São duas etapas, com o mesmo consultor do começo ao fim."},{"li":false,"t":"Na visita, ele apresenta os espaços que fazem sentido para o tamanho da sua lista e para o formato que você imaginou. Depois vem a degustação, com um menu pensado para o seu aniversário, e não com um cardápio padrão."},{"li":false,"t":"Esse mesmo consultor acompanha você durante o planejamento e no pós-evento."}]},{"q":"Como solicitar um orçamento de aniversário?","a":[{"li":false,"t":"Preencha o formulário desta página ou fale diretamente com a nossa equipe pelo WhatsApp."},{"li":false,"t":"Ajuda ter três informações em mãos: a data prevista, o número aproximado de convidados e o formato que você imagina para a celebração. A equipe do TRIO retorna em até 24 horas úteis com uma proposta personalizada."},{"li":false,"t":"O mesmo atendimento está disponível para casamento, festa de 15 anos, mini wedding, Bar e Bat Mitzvah e eventos corporativos."}]}],"numbers":[],"eyebrow":"PERGUNTAS FREQUENTES","title":"Tudo sobre aniversário no Grupo TRIO","link":"FALAR COM A EQUIPE","key":"faq"},{"name":"CONTATO","paras":["Conte para a nossa equipe como você está imaginando a sua celebração.","Preencha o formulário ou fale diretamente pelo WhatsApp. A partir da data, do número de convidados e do formato que você deseja, ajudamos a encontrar o espaço e a proposta que mais combinam com o seu aniversário.","Retornamos em até 24 horas úteis com uma proposta personalizada e, se fizer sentido, já agendamos a sua visita."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"CONTATO","title":"Vamos planejar seu aniversário?","formFields":["nome completo","e-mail","telefone","tipo de evento","data prevista","nº de convidados","mensagem"],"cta1":"ENVIAR SOLICITAÇÃO","key":"contato"}]},"barmitzvah":{"meta":{"title":"Espaço para Bar Mitzvah em SP com menu kosher | Grupo TRIO","description":"10 espaços para Bar e Bat Mitzvah em São Paulo, com cozinha kosher certificada pela Beit Yaacov, equipe própria e estrutura para celebrar com a família.","url":"https://www.grupotrio.com.br/bar-mitzvah/"},"blocks":[{"name":"HERO","paras":["Uma celebração que reúne gerações, histórias e pessoas importantes em um mesmo lugar. O Grupo TRIO oferece 10 espaços para Bar e Bat Mitzvah em São Paulo, com cozinha kosher certificada pela Beit Yaacov, equipe própria e estrutura completa para receber sua família e seus convidados."],"cards":[],"spaces":[],"faqs":[],"numbers":[{"value":"10","label":"ESPAÇOS EM SÃO PAULO"},{"value":"650","label":"CONVIDADOS NO SP HALL"},{"value":"3","label":"DÉCADAS RECEBENDO FAMÍLIAS"}],"eyebrow":"OCASIÃO · BAR E BAT MITZVAH","title":"Espaços para Bar e Bat Mitzvah em São Paulo","cta1":"QUERO FAZER MEU BAR MITZVAH","cta2":"VER ESPAÇOS","link":"FALAR NO WHATSAPP","key":"hero"},{"name":"SOBRE A EXPERIÊNCIA","paras":["Um Bar Mitzvah reúne pessoas que fazem parte da história de uma família. Avós, pais, irmãos, amigos e convidados que chegam de longe para estar juntos em um dia tão importante.","Por isso, para nós, tudo começa muito antes da festa.","A cozinha é kosher certificada pela Beit Yaacov, com supervisão do Rabino Alberto Safra. A produção é feita pela nossa própria equipe, com cuidado em cada etapa, do planejamento do menu ao serviço à mesa.","E vocês têm um ponto de contato próximo durante todo o processo, do primeiro encontro ao pós-evento. Há três décadas o Grupo TRIO recebe famílias da comunidade judaica em São Paulo, e a maior parte delas chega pela indicação de quem já celebrou aqui."],"cards":[{"num":"01","title":"COZINHA KOSHER CERTIFICADA","desc":"Certificação Beit Yaacov e supervisão do Rabino Alberto Safra, com menu desenvolvido junto com a família."},{"num":"02","title":"NOSSOS ENDEREÇOS","desc":"Berrini, Vila Olímpia, Butantã e Bela Vista. Valet, segurança e ar-condicionado em todos os espaços."},{"num":"03","title":"ATÉ 650 CONVIDADOS","desc":"Diferentes capacidades para coquetel e jantar, permitindo escolher o espaço de acordo com o tamanho da lista e o formato da celebração."},{"num":"04","title":"RECEPÇÃO E FESTA NO MESMO ENDEREÇO","desc":"Salão, foyer e áreas de apoio que permitem receber os convidados com tranquilidade antes do início da celebração."}],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"A CELEBRAÇÃO CUIDADA DE PERTO","title":"Tradição, cuidado e atenção aos detalhes","cta1":"RECEBER UMA PROPOSTA","link":"FALAR NO WHATSAPP","key":"sobre"},{"name":"LOCAIS","paras":[],"cards":[],"spaces":[{"name":"TRIO | TRIVENTO","meta":"Bela Vista · 620 m² entre salão, foyer e recepção · Até 600 convidados em coquetel.","paras":["Nosso endereço mais recente fica na Bela Vista, a poucos minutos de Higienópolis e dos Jardins.","Salão, foyer e recepção criam diferentes ambientes para a chegada dos convidados, a celebração e a festa.","Um espaço pensado para receber famílias grandes com conforto e liberdade para construir a celebração do seu jeito."],"feats":["Sala VIP","Valet","Acessibilidade","Ar-condicionado"],"key":"trivento"},{"name":"TRIO | SP HALL","meta":"Vila Olímpia · 840 m² · 650 em coquetel e 350 em jantar.","paras":["Dentro do São Paulo Corporate Towers, o SP HALL combina amplitude, área verde e pé-direito alto.","A altura abre espaço para cenografia suspensa, projeção e estruturas de iluminação, e o uso do espaço é exclusivo da sua celebração.","É o maior salão único do TRIO, para celebrações de grande porte que pedem liberdade de montagem."],"feats":["Camarim","Salas de apoio","Edifício LEED","Acessibilidade"],"key":"sphall"},{"name":"TRIO | PÉRGOLA","meta":"Berrini · Mais de 800 m² até 500 em coquetel e 350 em jantar.","paras":["No Berrini One, as janelas panorâmicas acompanham a queda do sol.","O PÉRGOLA funciona como respiro entre o jantar e a pista, e a sala VIP recebe a família próxima antes da entrada.","É o espaço que reúne o maior número de recursos do grupo, com heliponto no edifício para os registros do dia."],"feats":["Heliponto","Sala VIP","Terraço","Valet","Edifício LEED"],"key":"pergola"},{"name":"TRIO | DEZENOVE","meta":"Vila Olímpia, 19º andar · 280 m² · 200 em coquetel e 120 em jantar.","paras":["No E-Tower, na Rua Funchal, o DEZENOVE traz o skyline da Vila Olímpia para dentro da festa.","O jardim interno traz luz natural para dentro do salão, e o ambiente se mantém reservado mesmo com a vista aberta.","Atende às celebrações de lista fechada, entre familiares e amigos próximos."],"feats":["Heliponto","Jardim interno","Camarim","Sala VIP","Gerador"],"key":"dezenove"},{"name":"TRIO | SKY LOUNGE","meta":"Berrini, 34º andar · 280 m² · Até 180 convidados em coquetel.","paras":["No ponto mais alto do grupo, a cidade aparece inteira pela vidraça.","O teto em balanço amplia a sensação de espaço, e a vista acompanha a celebração do fim da tarde à noite.","É a escolha para listas mais curtas, em jantar sentado ou coquetel reduzido."],"feats":["Heliponto","Vista panorâmica","Acessibilidade","Edifício LEED"],"key":"skylounge"},{"name":"TRIO | ONE","meta":"Berrini, 8º andar · 230 m² · 200 em coquetel e 120 em jantar.","paras":["A lateral envidraçada faz a cidade virar cenário.","A iluminação dimerizada acompanha a noite inteira, do brinde de entrada à última música."],"feats":["Camarim","Heliponto para fotos","Terraço","Valet","Ar-condicionado"],"key":"one"},{"name":"TRIO | GARDEN","meta":"Butantã · 270 m² · até 200 convidados em coquetel e 120 em jantar.","paras":["No térreo do Edifício River One, mais de 25 espécies de plantas cercam o salão do GARDEN.","A luz natural entra o dia inteiro e muda a fotografia por completo.","É a escolha para celebrações durante o dia ou ao ar livre, sem sair da cidade."],"feats":["Natureza integrada","Térreo","Gerador","Edifício LEED","Acessibilidade"],"key":"garden"},{"name":"TRIO | RIVER ONE","meta":"Butantã · 370 m² · até 200 convidados em coquetel e 100 em jantar.","paras":["A projeção mapeada em 360º transforma as paredes em parte da decoração.","Atende bem às celebrações com homenagem em vídeo, apresentação ou cenografia autoral."],"feats":["Projeção mapeada 360º","Estrutura audiovisual","Amplo foyer","Camarim"],"key":"riverone"}],"faqs":[],"numbers":[],"eyebrow":"LOCAIS","title":"Espaços para Bar Mitzvah por região de São Paulo","lead":"Diferentes espaços, diferentes possibilidades. A escolha pode começar pelo tamanho da lista, pelo formato da celebração ou pela localização que faz mais sentido para a sua família. Conheça cada endereço e encontre o espaço que combina com o seu Bar Mitzvah.","key":"locais"},{"name":"VISTA","paras":["Uma vista também pode fazer parte da memória de um dia importante.","Nos espaços do Grupo TRIO, a cidade aparece pelas janelas, nos terraços e nos registros da celebração. Do 19º andar, no TRIO | DEZENOVE, ao horizonte aberto dos andares mais altos, São Paulo acompanha a festa sem tirar o protagonismo do que realmente importa: as pessoas reunidas à mesma mesa."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"CENÁRIO","title":"São Paulo como parte da celebração","cta1":"QUERO ESSE CENÁRIO","link":"VER ESPAÇOS COM VISTA","key":"vista"},{"name":"GASTRONOMIA","paras":["Em um Bar Mitzvah, a gastronomia precisa acolher todos os convidados.","No Grupo TRIO, a cozinha é kosher certificada pela Beit Yaacov, sob supervisão do Rabino Alberto Safra. O menu é produzido pela nossa própria equipe e desenvolvido junto com a família.","A inspiração vem da gastronomia mediterrânea, e o cardápio é apresentado em uma degustação antes da celebração. Assim, vocês podem provar e escolher com tranquilidade cada detalhe do menu.","Do avô que mantém a tradição há décadas ao amigo que está conhecendo a celebração pela primeira vez, todos podem compartilhar a mesma mesa."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"GASTRONOMIA KOSHER","title":"Uma cozinha que respeita a tradição e celebra à mesa","cta1":"SOLICITAR CARDÁPIO","key":"gastro"},{"name":"PERGUNTAS FREQUENTES","paras":[],"cards":[],"spaces":[],"faqs":[{"q":"A cozinha do Grupo TRIO é kosher certificada?","a":[{"li":false,"t":"Sim. A cozinha é certificada pela Beit Yaacov, com supervisão do Rabino Alberto Safra."},{"li":false,"t":"A produção é feita pela nossa própria equipe, sem buffet terceirizado. Isso permite acompanhar de perto toda a operação, do fornecedor ao serviço à mesa."}]},{"q":"É possível servir um menu não kosher?","a":[{"li":false,"t":"Sim, para as famílias que preferem esse formato."}]},{"q":"Qual é a capacidade dos espaços para Bar Mitzvah?","a":[{"li":false,"t":"A capacidade varia de acordo com o formato da celebração. Em um coquetel, os convidados circulam pelo espaço e a capacidade é maior. Em um jantar sentado, é necessário considerar as mesas e o conforto de todos."},{"li":false,"t":"Em coquetel"},{"li":true,"t":"TRIO | SP HALL, até 650 convidados"},{"li":true,"t":"TRIO | TRIVENTO, até 600 convidados"},{"li":true,"t":"TRIO | PÉRGOLA, até 500"},{"li":true,"t":"TRIO | DEZENOVE, até 200"},{"li":true,"t":"TRIO | ONE, até 200"},{"li":true,"t":"TRIO | GARDEN, até 200"},{"li":true,"t":"TRIO | RIVER ONE, até 200"},{"li":true,"t":"TRIO | SKY LOUNGE, até 180"},{"li":false,"t":"Em jantar sentado"},{"li":true,"t":"TRIO | TRIVENTO, até 350"},{"li":true,"t":"TRIO | SP HALL, até 350"},{"li":true,"t":"TRIO | PÉRGOLA, até 350"},{"li":true,"t":"TRIO | DEZENOVE, até 120"},{"li":true,"t":"TRIO | ONE, até 120"},{"li":true,"t":"TRIO | GARDEN, até 120"},{"li":true,"t":"TRIO | RIVER ONE, até 100"}]},{"q":"Em quais bairros de São Paulo ficam os espaços para Bar Mitzvah?","a":[{"li":false,"t":"Os espaços estão distribuídos pela Zona Sul e por importantes eixos da cidade."},{"li":true,"t":"Bela Vista, TRIO | TRIVENTO."},{"li":true,"t":"Vila Olímpia, TRIO | SP HALL, no São Paulo Corporate Towers."},{"li":true,"t":"Berrini, TRIO | PÉRGOLA, no Edifício Berrini One."},{"li":true,"t":"Vila Olímpia, TRIO | DEZENOVE, no 19º andar do E-Tower."},{"li":true,"t":"Butantã, TRIO | GARDEN, no Edifício River One."},{"li":true,"t":"Berrini, TRIO | SKY LOUNGE, no 34º andar do Edifício Berrini One."},{"li":true,"t":"Butantã, TRIO | RIVER ONE no Edifício River One."},{"li":true,"t":"Berrini, TRIO | ONE, no 8º andar do Edifício Berrini One."},{"li":false,"t":"O acesso ao Butantã é facilitado pela Marginal Pinheiros e pelas avenidas Faria Lima e Rebouças."}]},{"q":"A festa acontece no mesmo endereço da cerimônia?","a":[{"li":false,"t":"A leitura da Torá acontece na sinagoga da família. No Grupo TRIO, recebemos a celebração que vem depois."},{"li":false,"t":"Nos espaços que possuem áreas independentes do salão, a chegada dos convidados e os primeiros momentos da celebração podem acontecer no foyer ou em outros ambientes antes da abertura do salão principal."},{"li":false,"t":"No TRIO | TRIVENTO, por exemplo, o foyer e a recepção ficam separados do salão principal. No TRIO | PÉRGOLA, são 200 m² de pérgola integrados aos 600 m² de salão."}]},{"q":"O menu se adapta a restrições alimentares além do kosher?","a":[{"li":false,"t":"Sim. Além da linha kosher, trabalhamos com opções parve, veganas, vegetarianas e adaptações para restrições alimentares específicas."},{"li":false,"t":"Essas necessidades são consideradas durante o desenvolvimento do menu, antes da degustação, para que tudo seja planejado com antecedência."}]},{"q":"Como solicitar um orçamento de Bar Mitzvah?","a":[{"li":false,"t":"Você pode preencher o formulário desta página ou falar diretamente com a nossa equipe pelo WhatsApp."},{"li":false,"t":"Se já tiver essas informações, envie a data prevista, o número aproximado de convidados e o formato desejado. Assim, conseguimos entender melhor a celebração e indicar os espaços mais adequados."},{"li":false,"t":"Nossa equipe retorna em até 24 horas úteis com uma proposta personalizada."},{"li":false,"t":"O mesmo canal também pode ser utilizado para solicitar informações sobre casamento, festa de 15 anos, aniversário, mini wedding e corporativo."}]}],"numbers":[],"eyebrow":"PERGUNTAS FREQUENTES","title":"Tudo sobre Bar e Bat Mitzvah no Grupo TRIO","link":"FALAR COM A EQUIPE","key":"faq"},{"name":"CONTATO","paras":["Toda celebração começa com uma conversa.","Conte para a nossa equipe a data, o número de convidados e o que vocês imaginam para esse dia. A partir daí, apresentamos os espaços, possibilidades de menu e estrutura que fazem sentido para a sua família.","O retorno acontece em até 24 horas úteis, e a visita ao espaço pode ser agendada na mesma conversa."],"cards":[],"spaces":[],"faqs":[],"numbers":[],"eyebrow":"CONTATO","title":"Vamos planejar o seu Bar Mitzvah?","formFields":["nome completo","e-mail","telefone","tipo de evento","data prevista","nº de convidados","mensagem"],"cta1":"ENVIAR SOLICITAÇÃO","key":"contato"}]}};